import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import ProductCard from '../components/ProductCard';
import WhiteButtonMenu from '../utils/WhiteButtonMenu';
import { useCart } from '../context/CartContext';


//const API_URL = "http://143.110.239.79:5010"; // tu base URL del backend
const API_URL = "https://lajuanita.mindnt.com.mx";
//const API_URL = "http://localhost:5010"; // tu base URL del backend


const MenuSection = ({ reloadFlag }) => {
  const [categories, setCategories] = useState([]);
  const [activeCategory, setActiveCategory] = useState(null);
  const [products, setProducts] = useState([]); // 🔹 productos del día
  const { addItem } = useCart();

  // 🔹 1. Obtener fecha actual en formato YYYY-MM-DD (horario de México)
  const getTodayDate = () => {
    const today = new Date();
    // Convertir a horario de México (UTC-6 o UTC-5 dependiendo del horario de verano)
    const mexicoDate = new Date(today.toLocaleString("en-US", {timeZone: "America/Mexico_City"}));
    const year = mexicoDate.getFullYear();
    const month = String(mexicoDate.getMonth() + 1).padStart(2, '0');
    const day = String(mexicoDate.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  // 🔹 1.1. Obtener fecha de mañana en formato YYYY-MM-DD (horario de México)
  const getTomorrowDate = () => {
    const today = new Date();
    // Convertir a horario de México
    const mexicoDate = new Date(today.toLocaleString("en-US", {timeZone: "America/Mexico_City"}));
    // Sumar un día
    const tomorrow = new Date(mexicoDate.getFullYear(), mexicoDate.getMonth(), mexicoDate.getDate() + 1);
    const year = tomorrow.getFullYear();
    const month = String(tomorrow.getMonth() + 1).padStart(2, '0');
    const day = String(tomorrow.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  // 🔹 1.2. Determinar qué fecha usar para el menú según la hora actual
  const getMenuDate = () => {
    const now = new Date();
    // Convertir a horario de México para obtener la hora local correcta
    const mexicoDate = new Date(now.toLocaleString("en-US", {timeZone: "America/Mexico_City"}));
    const currentHour = mexicoDate.getHours();
    
    // Después de las 15:00 (3 PM) -> mostrar menú de mañana
    if (currentHour >= 15) {
      return getTomorrowDate();
    }
    
    // Antes de las 15:00 -> mostrar menú de hoy
    return getTodayDate();
  };

  // 🔹 2. Cargar categorías desde el backend
  useEffect(() => {
    const fetchCategories = async () => {
      try {
        const res = await fetch(`${API_URL}/items/categories`);
        const json = await res.json();
        if (json.status === "success") {
          const activeCats = json.data.filter(cat => cat.is_active === 1);
          setCategories(activeCats);
          setActiveCategory(activeCats[0]?.id || null); // usar id como clave
        }
      } catch (error) {
        console.error("❌ Error al obtener categorías:", error);
      }
    };
    fetchCategories();
  }, []);

  // Add this function to format Google Drive URLs
  const formatGoogleDriveUrl = (url) => {
    if (!url) return '';
    
    // Extract the file ID from various Google Drive URL formats
    let fileId = '';
    
    // Format 1: https://drive.google.com/file/d/FILEID/view...
    const fileIdMatch = url.match(/\/d\/(.*?)(\/|$|\?)/);
    if (fileIdMatch) {
      fileId = fileIdMatch[1];
    }
    
    // Format 2: Already has the ID in uc?export=view format
    const ucMatch = url.match(/id=(.*?)($|&)/);
    if (ucMatch) {
      fileId = ucMatch[1];
    }

    if (!fileId) return url;
    
    // Use the direct download URL format
    return `https://drive.google.com/thumbnail?id=${fileId}&sz=w1000`;
  };

  // 🔹 3. Cargar productos del día según fecha actual (dinámica: hoy antes de 15:00, mañana después)
  useEffect(() => {
    const fetchProducts = async () => {
      try {
        const menuDate = getMenuDate(); // 🔹 Usar fecha dinámica
        const res = await fetch(`${API_URL}/items/get-items-day?day=${menuDate}`);
        const json = await res.json();
        if (json.status === "success") {
          // Format the image URLs before setting the products
          const formattedProducts = json.data.map(product => ({
            ...product,
            img_item: formatGoogleDriveUrl(product.img_item)
          }));
          setProducts(formattedProducts);
        }
      } catch (error) {
        console.error("❌ Error al obtener productos:", error);
      }
    };
    fetchProducts();
  }, [reloadFlag]);

  // 🔹 4. Agregar producto al carrito
  const handleAddClick = (product) => addItem(product);

  // 🔹 5. Cambiar categoría activa
  const handleCategoryClick = (categoryId) => setActiveCategory(categoryId);

  // 🔹 6. Filtrar productos por categoría activa
  const filteredProducts = products.filter(p => p.category_id === activeCategory);

  // Animation variants
  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1,
        delayChildren: 0.2
      }
    }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.5,
        ease: "easeOut"
      }
    }
  };

  const categoryButtonVariants = {
    hidden: { opacity: 0, scale: 0.8 },
    visible: {
      opacity: 1,
      scale: 1,
      transition: {
        duration: 0.3,
        ease: "easeOut"
      }
    }
  };

  const productGridVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1,
        delayChildren: 0.1
      }
    },
    exit: {
      opacity: 0,
      transition: {
        duration: 0.2
      }
    }
  };

  const productCardVariants = {
    hidden: { opacity: 0, y: 30, scale: 0.9 },
    visible: {
      opacity: 1,
      y: 0,
      scale: 1,
      transition: {
        duration: 0.4,
        ease: "easeOut"
      }
    },
    exit: {
      opacity: 0,
      y: -20,
      scale: 0.95,
      transition: {
        duration: 0.2
      }
    }
  };

  return (
    <section className="w-full py-6 sm:py-16 px-4 md:px-6">
      <div className="container mx-auto">
        {/* Título */}
        <motion.h2 
          className="text-white text-2xl sm:text-4xl lg:text-5xl font-bold mb-4 text-left"
          initial={{ opacity: 0, x: -50 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.6, ease: "easeOut" }}
        >
          Descubre nuestro menú del día
        </motion.h2>

        {/* Subtítulo informativo */}
        <motion.p 
          className="text-white/80 text-sm sm:text-base mb-8 text-left flex items-center gap-2"
          initial={{ opacity: 0, x: -30 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.6, ease: "easeOut", delay: 0.2 }}
        >
          <svg className="w-4 h-4 sm:w-5 sm:h-5 text-white/60 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
          Explora nuestros platillos con toda la información disponible
        </motion.p>

        {/* Botones de categorías */}
        <motion.div 
          className="flex flex-wrap justify-center sm:justify-between lg:justify-start gap-2 sm:gap-4 lg:gap-8 xl:gap-12 mb-12"
          variants={containerVariants}
          initial="hidden"
          animate="visible"
        >
          {categories.length > 0 ? (
            categories.map((category, index) => (
              <motion.div
                key={category.id}
                variants={categoryButtonVariants}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                className="flex-shrink-0"
              >
                <WhiteButtonMenu
                  text={category.name}
                  isActive={activeCategory === category.id}
                  onClick={() => handleCategoryClick(category.id)}
                />
              </motion.div>
            ))
          ) : (
            <motion.p 
              className="text-white"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ duration: 0.5, repeat: Infinity, repeatType: "reverse" }}
            >
              Cargando categorías...
            </motion.p>
          )}
        </motion.div>

        {/* Grid de productos */}
        <AnimatePresence mode="wait">
          {filteredProducts.length > 0 ? (
            <motion.div 
              key={activeCategory}
              className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 sm:gap-6 lg:gap-8 justify-items-center"
              variants={productGridVariants}
              initial="hidden"
              animate="visible"
              exit="exit"
            >
              {filteredProducts.map((item, index) => (
                <motion.div
                  key={item.id}
                  variants={productCardVariants}
                  whileHover={{ 
                    scale: 1.03,
                    transition: { duration: 0.2 }
                  }}
                  layout
                  className="w-full max-w-sm" // Eliminamos altura fija y agregamos max-width
                >
                  <ProductCard
                    id={item.id}
                    image={item.img_item}
                    title={item.Nombre}
                    description={item.description || 'Sin descripción'}
                    price={item.price}
                    availability={item.product_counter || 0}
                    applyPromotions={item.apply_promotions}
                    onAddClick={() => handleAddClick(item)}
                  />
                </motion.div>
              ))}
            </motion.div>
          ) : (
            <motion.p 
              key="no-products"
              className="text-white text-center"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              transition={{ duration: 0.3 }}
            >
              No hay productos disponibles para esta categoría hoy.
            </motion.p>
          )}
        </AnimatePresence>
      </div>
    </section>
  );
};

export default MenuSection;
