import React, { useState } from 'react';
import { motion, AnimatePresence } from 'motion/react';

const ModalSuccess = ({ isOpen, onClose, orderData, orderCode }) => {
  const [showCustomerDetails, setShowCustomerDetails] = useState(false);

  if (!isOpen || !orderData) return null;

  const formatDisplayTime = (hour, minute) => {
    const numHour = parseInt(hour, 10);
    const numMinute = parseInt(minute, 10);
    const ampm = numHour >= 12 ? 'p.m.' : 'a.m.';
    const displayHour = numHour > 12 ? numHour - 12 : numHour === 0 ? 12 : numHour;
    return `${displayHour}:${numMinute.toString().padStart(2, '0')} ${ampm}`;
  };

  const formatDate = (dateStr) => {
    const [year, month, day] = dateStr.split('-');
    return `${day}/${month}/${year}`;
  };

  const getDeliveryInfo = () => {
    if (orderData.deliveryType === 'pickup') {
      return {
        type: 'Recoger en tienda',
        address: 'Morelia 707, Zaragoza, Montemorelos, NL'
      };
    } else if (orderData.deliveryType === 'delivery') {
      return {
        type: 'A domicilio',
        address: 'Tu ubicación actual'
      };
    } else if (orderData.deliveryType === 'someone_else') {
      const fullAddress = `${orderData.customAddress.street.trim()} ${orderData.customAddress.number.trim()}, ${orderData.customAddress.neighborhood.trim()}, Montemorelos, NL`;
      return {
        type: 'A otra ubicación',
        address: fullAddress
      };
    }
  };

  const deliveryInfo = getDeliveryInfo();
  const currentDate = new Date();
  const formattedCurrentDate = `${currentDate.getDate().toString().padStart(2, '0')}/${(currentDate.getMonth() + 1).toString().padStart(2, '0')}/${currentDate.getFullYear()}`;
  const formattedCurrentTime = `${currentDate.getHours().toString().padStart(2, '0')}:${currentDate.getMinutes().toString().padStart(2, '0')} ${currentDate.getHours() >= 12 ? 'p.m.' : 'a.m.'}`;

  return (
    <div className="fixed inset-0 z-50 overflow-hidden">
      {/* Animated Green Background */}
      <motion.div
        className="absolute inset-0 bg-gradient-to-br from-green-600 via-green-700 to-green-800"
        initial={{ clipPath: "circle(0% at 50% 50%)" }}
        animate={{ clipPath: "circle(150% at 50% 50%)" }}
        transition={{ duration: 0.8, ease: "easeInOut" }}
      />

      {/* Content Container */}
      <div className="relative z-10 flex items-center justify-center min-h-screen p-3 sm:p-4 md:p-6 lg:p-8">
        <motion.div
          className="relative w-full max-w-[95%] sm:max-w-lg md:max-w-xl lg:max-w-2xl xl:max-w-3xl my-4 sm:my-6 lg:my-8"
          initial={{ opacity: 0, scale: 0.9, y: 30 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          transition={{ delay: 0.4, duration: 0.5, ease: "easeOut" }}
        >
          {/* Close button - Top right */}
          <button
            onClick={onClose}
            className="absolute -top-10 sm:-top-12 right-0 text-white/90 hover:text-white transition-all duration-200 z-20 p-2 hover:bg-white/10 rounded-full"
          >
            <svg className="w-5 h-5 sm:w-6 sm:h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>

          {/* White Ticket Card */}
          <div className="bg-white rounded-2xl sm:rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[85vh] sm:max-h-[90vh]">

            {/* Header - Green bar with LA JUANITA and Comprobante */}
            <div className="bg-green-700 px-4 sm:px-5 md:px-6 py-3 sm:py-4 flex justify-between items-center flex-shrink-0">
              <h1 className="text-white font-bold text-lg sm:text-xl md:text-2xl tracking-wide">LA JUANITA</h1>
              <div className="text-right">
                <p className="text-white font-semibold text-xs sm:text-sm md:text-base">Comprobante</p>
                <p className="text-white/90 text-[10px] sm:text-xs md:text-sm">{formattedCurrentDate} · {formattedCurrentTime}</p>
              </div>
            </div>

            {/* Main Content - Scrollable */}
            <div className="px-4 sm:px-5 md:px-6 lg:px-8 xl:px-10 py-6 sm:py-7 md:py-8 lg:py-10 overflow-y-auto flex-1">

              {/* Success Message with Checkmark */}
              <motion.div
                className="flex items-start mb-6 sm:mb-7 md:mb-8"
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: 0.6, duration: 0.4 }}
              >
                {/* Checkmark Circle */}
                <div className="flex-shrink-0 w-10 h-10 sm:w-12 sm:h-12 md:w-14 md:h-14 bg-green-100 rounded-full flex items-center justify-center mr-3 sm:mr-4">
                  <svg className="w-5 h-5 sm:w-6 sm:h-6 md:w-7 md:h-7 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                  </svg>
                </div>

                {/* Message */}
                <div className="flex-1">
                  <h2 className="text-xl sm:text-2xl md:text-3xl font-bold text-gray-900 mb-1">Pedido recibido</h2>
                  <p className="text-gray-600 text-xs sm:text-sm md:text-base">
                    Guarda tu número de orden. Lo usaremos para entregarte.
                  </p>
                </div>
              </motion.div>

              {/* Order Number - Large Display */}
              <motion.div
                className="mb-6 sm:mb-7 md:mb-8"
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.8, duration: 0.4 }}
              >
                <p className="text-gray-600 text-xs sm:text-sm md:text-base font-medium mb-1 sm:mb-2 uppercase tracking-wide">Número de orden</p>
                <div className="text-5xl sm:text-6xl md:text-7xl lg:text-8xl font-black text-gray-900 leading-none">
                  {orderCode}
                </div>
              </motion.div>

              {/* Delivery Details */}
              <motion.div
                className="bg-gray-50 rounded-xl sm:rounded-2xl p-4 sm:p-5 md:p-6 mb-5 sm:mb-6"
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 1.0, duration: 0.4 }}
              >
                {/* Entrega Row */}
                <div className="flex justify-between items-start mb-3 sm:mb-4 pb-3 sm:pb-4 border-b border-gray-200">
                  <span className="text-gray-600 text-xs sm:text-sm md:text-base font-medium">Entrega</span>
                  <div className="text-right">
                    <span className="inline-block bg-gray-900 text-white text-[10px] sm:text-xs md:text-sm font-bold px-2 sm:px-3 py-1 rounded-full">
                      {deliveryInfo.type}
                    </span>
                  </div>
                </div>

                {/* Cuándo Row */}
                <div className="flex justify-between items-center mb-3 sm:mb-4 pb-3 sm:pb-4 border-b border-gray-200">
                  <span className="text-gray-600 text-xs sm:text-sm md:text-base font-medium">Cuándo</span>
                  <span className="text-gray-900 text-xs sm:text-sm md:text-base font-bold text-right">
                    {formatDate(orderData.customerInfo.date)} · {formatDisplayTime(orderData.customerInfo.hour, orderData.customerInfo.minute)}
                  </span>
                </div>

                {/* Dónde Row */}
                <div className="flex justify-between items-start gap-3">
                  <span className="text-gray-600 text-xs sm:text-sm md:text-base font-medium flex-shrink-0">Dónde</span>
                  <span className="text-gray-900 text-xs sm:text-sm md:text-base font-bold text-right">
                    {deliveryInfo.address}
                  </span>
                </div>
              </motion.div>

              {/* Total Pagado */}
              <motion.div
                className="flex justify-between items-center mb-5 sm:mb-6 pb-5 sm:pb-6 border-b border-gray-200"
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 1.2, duration: 0.4 }}
              >
                <span className="text-gray-600 text-sm sm:text-base md:text-lg font-medium uppercase tracking-wide">Total pagado</span>
                <span className="text-gray-900 text-xl sm:text-2xl md:text-3xl font-black">
                  ${orderData.totalPrice} MXN
                </span>
              </motion.div>

              {/* Ver datos del cliente - Collapsible */}
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 1.4, duration: 0.4 }}
              >
                <button
                  onClick={() => setShowCustomerDetails(!showCustomerDetails)}
                  className="w-full flex justify-between items-center py-3 sm:py-4 px-4 sm:px-5 bg-gray-50 hover:bg-gray-100 rounded-xl transition-colors duration-200 group"
                >
                  <span className="text-gray-700 font-semibold text-xs sm:text-sm md:text-base">Ver datos del cliente</span>
                  <motion.svg
                    className="w-4 h-4 sm:w-5 sm:h-5 text-gray-600 group-hover:text-gray-900 transition-colors flex-shrink-0"
                    animate={{ rotate: showCustomerDetails ? 180 : 0 }}
                    transition={{ duration: 0.3 }}
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                  </motion.svg>
                </button>

                {/* Collapsible Customer Details */}
                <AnimatePresence>
                  {showCustomerDetails && (
                    <motion.div
                      initial={{ height: 0, opacity: 0 }}
                      animate={{ height: "auto", opacity: 1 }}
                      exit={{ height: 0, opacity: 0 }}
                      transition={{ duration: 0.3 }}
                      className="overflow-hidden"
                    >
                      <div className="pt-3 sm:pt-4 px-4 sm:px-5 space-y-2 sm:space-y-3">
                        <div className="flex justify-between items-center gap-3">
                          <span className="text-gray-600 text-xs sm:text-sm">Nombre:</span>
                          <span className="text-gray-900 text-xs sm:text-sm font-medium text-right">
                            {orderData.customerInfo.name || 'Cliente registrado'}
                          </span>
                        </div>
                        <div className="flex justify-between items-center gap-3">
                          <span className="text-gray-600 text-xs sm:text-sm">Teléfono:</span>
                          <span className="text-gray-900 text-xs sm:text-sm font-medium text-right">
                            {orderData.customerInfo.phone}
                          </span>
                        </div>
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </motion.div>

              {/* Footer Message */}
              <motion.div
                className="mt-6 sm:mt-7 md:mt-8 pt-5 sm:pt-6 border-t border-gray-200"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 1.6, duration: 0.4 }}
              >
                <p className="text-center text-gray-700 text-xs sm:text-sm md:text-base leading-relaxed">
                  Recibe tu pedido con tu <span className="font-bold underline decoration-green-600 decoration-2">número de orden</span> o tu <span className="font-bold underline decoration-green-600 decoration-2">celular</span>.
                </p>
              </motion.div>

            </div>
          </div>
        </motion.div>
      </div>
    </div>
  );
};

export default ModalSuccess;
